async function enterpriseVisionActionDispatch(c:any,i:any){
  const ctx=i.enterpriseContext;
  if(!ctx||ctx.surface!=="enterprise_vision")return null;
  const message=txt(i.message),lower=message.toLowerCase(),cameraId=visionSelectedCamera(ctx),minutes=visionWindowMinutes(message);
  if(/\b(alert|notify|watch for|tell me when)\b/.test(lower)){
    if(!cameraId)return persistEnterpriseVisionDirect(c,i,"Choose an authorized camera first so Pandora can scope that alert rule.",{verified:true,provider:"pandora-vision",action:"rule_not_created",reason:"camera_required"});
    const eventType=visionEventTypeFromInstruction(message),name=("Pandora · "+eventType.replaceAll("_"," ")).slice(0,160);
    const insert=await c.admin.from("enterprise_vision_rules").insert({organization_id:c.organizationId,camera_id:cameraId,name,event_types:[eventType],min_confidence:.65,severity:/\bcritical|emergency|immediately\b/.test(lower)?"critical":"warning",schedule:{instruction:message},notify_roles:["owner","admin"],enabled:true,created_by:c.userId}).select("id,name,event_types,severity,enabled").single();
    if(insert.error)throw Error("BACKEND_WRITE_FAILED");
    return persistEnterpriseVisionDirect(c,i,"Vision alert rule created for "+eventType.replaceAll("_"," ")+". It will apply to new analyzed events from the selected authorized camera.",{verified:true,provider:"pandora-vision",action:"create_rule",rule:insert.data,cameraId});
  }
  if(/\b(extract|save|keep|show)\b.{0,24}\b(clip|footage|video)\b|\bclip\b.{0,24}\b(last|past|previous)\b/.test(lower)){
    if(!cameraId)return persistEnterpriseVisionDirect(c,i,"Choose an authorized camera first so Pandora knows which recording should supply the clip.",{verified:true,provider:"pandora-vision",action:"clip_not_requested",reason:"camera_required"});
    const endAt=new Date(),startAt=new Date(endAt.getTime()-minutes*60000);
    const q=await c.user.rpc("pandora_vision_request_clip_v1",{p_organization_id:c.organizationId,p_camera_id:cameraId,p_start_at:startAt.toISOString(),p_end_at:endAt.toISOString(),p_reason:message.slice(0,1000),p_event_id:null});
    if(q.error)throw Error("BACKEND_WRITE_FAILED");
    return persistEnterpriseVisionDirect(c,i,"Clip extraction requested for the selected authorized camera covering the last "+minutes+" minute"+(minutes===1?"":"s")+".",{verified:true,provider:"pandora-vision",action:"request_clip",cameraId,clipRequest:q.data});
  }
  if(/\b(create|generate|prepare)\b.{0,32}\bincident report\b/.test(lower)){
    const endAt=new Date(),startAt=new Date(endAt.getTime()-minutes*60000);
    const q=await c.user.rpc("pandora_vision_search_v1",{p_organization_id:c.organizationId,p_query:null,p_camera_id:cameraId,p_start_at:startAt.toISOString(),p_end_at:endAt.toISOString(),p_limit:100});
    if(q.error)throw Error("BACKEND_READ_FAILED");
    const events=Array.isArray(rec(q.data).events)?rec(q.data).events as any[]:[];
    if(!events.length)return persistEnterpriseVisionDirect(c,i,"No stored Vision events are available in that window, so Pandora did not create an empty incident report.",{verified:true,provider:"pandora-vision",action:"incident_not_created",reason:"no_events"});
    const titles=events.slice(0,12).map(x=>txt(rec(x).title)).filter(Boolean),severity=events.some(x=>txt(rec(x).severity)==="critical")?"critical":events.some(x=>txt(rec(x).severity)==="warning")?"warning":"info",summary=("Machine-observed Vision events in the selected window: "+titles.join("; ")).slice(0,6000);
    const created=await c.admin.from("enterprise_vision_incidents").insert({organization_id:c.organizationId,title:"Vision incident · "+new Date().toISOString().slice(0,16).replace("T"," "),summary,severity,status:"reviewing",started_at:txt(rec(events[events.length-1]).startedAt,startAt.toISOString()),ended_at:txt(rec(events[0]).endedAt,txt(rec(events[0]).startedAt,endAt.toISOString())),event_ids:events.map(x=>txt(rec(x).id)).filter(Boolean).slice(0,100),report:{machineGenerated:true,verified:false,requestedInstruction:message},created_by:c.userId}).select("id,title,severity,status,created_at").single();
    if(created.error)throw Error("BACKEND_WRITE_FAILED");
    return persistEnterpriseVisionDirect(c,i,"Incident report created in reviewing state from "+events.length+" stored Vision event"+(events.length===1?"":"s")+". Machine observations remain unverified until reviewed.",{verified:true,provider:"pandora-vision",action:"create_incident",incident:created.data,eventCount:events.length});
  }
  const ack=message.match(/\b(?:acknowledge|resolve|dismiss)\s+(?:alert\s+)?([0-9a-f]{8}-[0-9a-f-]{27})\b/i);
  if(ack){
    const status=/\bresolve\b/i.test(message)?"resolved":/\bdismiss\b/i.test(message)?"dismissed":"acknowledged";
    const q=await c.user.rpc("pandora_vision_ack_alert_v1",{p_organization_id:c.organizationId,p_alert_id:ack[1],p_status:status});
    if(q.error)throw Error("BACKEND_WRITE_FAILED");
    return persistEnterpriseVisionDirect(c,i,"Vision alert "+status+".",{verified:true,provider:"pandora-vision",action:"ack_alert",alert:q.data});
  }
  const verify=message.match(/\b(verify|reject)\s+(?:observation\s+)?([0-9a-f]{8}-[0-9a-f-]{27})\b/i);
  if(verify){
    const state=verify[1].toLowerCase()==="reject"?"rejected":"verified";
    const q=await c.user.rpc("pandora_vision_verify_observation_v1",{p_organization_id:c.organizationId,p_observation_id:verify[2],p_state:state});
    if(q.error)throw Error("BACKEND_WRITE_FAILED");
    return persistEnterpriseVisionDirect(c,i,"Vision observation marked "+state+".",{verified:true,provider:"pandora-vision",action:"verify_observation",observation:q.data});
  }
  return null;
}

